CREATE TABLE "EmployeeBonus" ("id" TEXT NOT NULL PRIMARY KEY, "employeeId" TEXT NOT NULL, "month" TEXT NOT NULL, "name" TEXT NOT NULL, "amountCents" REAL NOT NULL, "reason" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmployeeBonus_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "EmployeeBonus_employeeId_month_idx" ON "EmployeeBonus"("employeeId", "month");
CREATE TABLE "EmployeeDeduction" ("id" TEXT NOT NULL PRIMARY KEY, "employeeId" TEXT NOT NULL, "month" TEXT NOT NULL, "name" TEXT NOT NULL, "amountCents" REAL NOT NULL, "reason" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmployeeDeduction_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "EmployeeDeduction_employeeId_month_idx" ON "EmployeeDeduction"("employeeId", "month");
CREATE TABLE "EmployeeAdvance" ("id" TEXT NOT NULL PRIMARY KEY, "employeeId" TEXT NOT NULL, "amountCents" REAL NOT NULL, "remainingCents" REAL NOT NULL, "issuedAt" DATETIME NOT NULL, "repaymentMode" TEXT NOT NULL DEFAULT 'NEXT_PAYROLL', "installmentCents" REAL, "source" TEXT NOT NULL DEFAULT 'EXECUTIVE_DIRECTOR', "status" TEXT NOT NULL DEFAULT 'OPEN', "note" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmployeeAdvance_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "EmployeeAdvance_employeeId_status_idx" ON "EmployeeAdvance"("employeeId", "status");
CREATE TABLE "PayrollRun" ("id" TEXT NOT NULL PRIMARY KEY, "month" TEXT NOT NULL UNIQUE, "status" TEXT NOT NULL DEFAULT 'APPROVED', "totalCents" REAL NOT NULL DEFAULT 0, "paymentSource" TEXT NOT NULL DEFAULT 'EXECUTIVE_DIRECTOR', "approvedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "paidAt" DATETIME, "approvedById" TEXT NOT NULL, "paidById" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PayrollRun_approvedById_fkey" FOREIGN KEY ("approvedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "PayrollRun_paidById_fkey" FOREIGN KEY ("paidById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "PayrollLine" ("id" TEXT NOT NULL PRIMARY KEY, "payrollRunId" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "basicCents" REAL NOT NULL, "bonusCents" REAL NOT NULL DEFAULT 0, "deductionCents" REAL NOT NULL DEFAULT 0, "advanceCents" REAL NOT NULL DEFAULT 0, "netCents" REAL NOT NULL, "allocationJson" TEXT NOT NULL, CONSTRAINT "PayrollLine_payrollRunId_fkey" FOREIGN KEY ("payrollRunId") REFERENCES "PayrollRun"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "PayrollLine_employeeId_fkey" FOREIGN KEY ("employeeId") REFERENCES "Employee"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PayrollLine_payrollRunId_employeeId_key" ON "PayrollLine"("payrollRunId", "employeeId");
CREATE TABLE "AdvanceInstallment" ("id" TEXT NOT NULL PRIMARY KEY, "advanceId" TEXT NOT NULL, "payrollLineId" TEXT, "dueMonth" TEXT NOT NULL, "amountCents" REAL NOT NULL, "appliedCents" REAL NOT NULL DEFAULT 0, CONSTRAINT "AdvanceInstallment_advanceId_fkey" FOREIGN KEY ("advanceId") REFERENCES "EmployeeAdvance"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "AdvanceInstallment_payrollLineId_fkey" FOREIGN KEY ("payrollLineId") REFERENCES "PayrollLine"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "AdvanceInstallment_advanceId_dueMonth_key" ON "AdvanceInstallment"("advanceId", "dueMonth");
CREATE TABLE "SalaryAttachment" ("id" TEXT NOT NULL PRIMARY KEY, "payrollRunId" TEXT, "advanceId" TEXT, "name" TEXT NOT NULL, "mime" TEXT NOT NULL, "size" INTEGER NOT NULL, "data" BLOB NOT NULL, "actorId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SalaryAttachment_payrollRunId_fkey" FOREIGN KEY ("payrollRunId") REFERENCES "PayrollRun"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SalaryAttachment_advanceId_fkey" FOREIGN KEY ("advanceId") REFERENCES "EmployeeAdvance"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "SalaryAttachment_payrollRunId_idx" ON "SalaryAttachment"("payrollRunId");
CREATE INDEX "SalaryAttachment_advanceId_idx" ON "SalaryAttachment"("advanceId");
